<script setup>
import TablePanel from '../../shared/components/TablePanel.vue';

import { vMoney } from './money-input.js';
import {computed,inject,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {amount,decimal,errorText,financeKey,matchesAccount,minor,money,positive,time} from './finance-model.js';
import FinancePagination from './FinancePagination.vue';
const vm=inject(financeKey),draft=reactive({to:'',transfer_id:'',amount:'',reason:''}),policyHours=ref(vm.options.funding_policy?.recovery_hours ?? 0),clock=ref(Date.now()),key=vm.key(),transfers=vm.resource('transfers'),history=vm.resource('recoveries');
let interval;
const selected=computed(()=>transfers.state.rows.find(row=>row.id===Number(draft.transfer_id)));
const recipients=computed(()=>vm.options.accounts.filter(row=>row.id!==vm.ownId.value && row.status==='active' && matchesAccount(row,{network:vm.ownId.value},vm.options.accounts)));
const eligible=computed(()=>transfers.state.rows.filter(row=>row.from_account_id===vm.ownId.value && row.to_account_id===Number(draft.to) && positive(row.remaining)));
const open=row=>row.recovery_deadline && Date.parse(row.recovery_deadline)>=clock.value && positive(row.remaining);
const limit=computed(()=>{if(!selected.value || !open(selected.value))return '0.00';const available=vm.walletAmount(selected.value.to_account_id,selected.value.service,selected.value.currency);if(available===null)return null;return decimal(minor(available)<minor(selected.value.remaining)?minor(available):minor(selected.value.remaining));});
function loadTransfers(page=1){if(!draft.to || !vm.service.value){transfers.dispose();return;}return transfers.load({account_id:draft.to,service:vm.service.value,currency:vm.currency.value,per_page:25,page,recoverable:1});}
function loadHistory(page=1){if(vm.emptyScope()){history.dispose();return;}return history.load(vm.recordParameters({per_page:25,page}));}
watch(()=>draft.to,()=>{draft.transfer_id='';draft.amount='';loadTransfers();});
watch(()=>draft.transfer_id,()=>{draft.amount='';});
watch([vm.service,vm.currency],()=>{draft.transfer_id='';draft.amount='';loadTransfers();loadHistory();});
watch(vm.filters,()=>loadHistory(),{deep:true});
watch(()=>vm.options.funding_policy?.recovery_hours,hours=>policyHours.value=hours ?? 0);
onMounted(()=>{loadHistory();interval=setInterval(()=>clock.value=Date.now(),1000);});onBeforeUnmount(()=>clearInterval(interval));
async function recover(){try{if(!selected.value || !open(selected.value))throw new Error('انتهت مهلة الاسترجاع أو العملية غير متاحة.');const value=amount(draft.amount);if(limit.value===null || minor(value)>minor(limit.value))throw new Error('المبلغ يتجاوز المتاح للاسترجاع.');const response=await vm.execute({amount:value,reason:draft.reason.trim()},key,body=>vm.api.action('transfers',selected.value.id,'recover',body),'تم استرجاع الرصيد إلى محفظتك.');if(response){draft.transfer_id='';draft.amount='';draft.reason='';await vm.refresh();await loadTransfers();await loadHistory();}}catch(failed){vm.error.value=errorText(failed);}}
async function saveHours(){const policy=vm.options.funding_policy;if(!policy)return;await vm.savePolicy({version:policy.version,daily_limit:policy.daily_limit,amounts:policy.amounts,recovery_hours:Number(policyHours.value)});}
</script>
<template><div class="recovery-page"><form v-if="vm.admin.value && vm.ownVisible.value && vm.can('security.fundingRequests') && vm.can('security.fundingRecovery')" class="card recovery-policy" @submit.prevent="saveHours"><label>المهلة · ساعات<input v-model="policyHours" type="number" min="1" max="720" step="1" required aria-label="مدة السماح باسترجاع الرصيد بالساعات"></label><button class="btn primary" :disabled="vm.busy.value">حفظ المهلة</button></form><form v-if="!vm.admin.value && vm.ownVisible.value && vm.can('wallets.reverse') && vm.service.value" class="card recovery-form" @submit.prevent="recover"><h3>استرجاع الرصيد</h3><div class="formgrid"><label>الحساب<select v-model="draft.to" required><option value="" disabled>اختر الحساب</option><option v-for="row in recipients" :key="row.id" :value="row.id">{{row.name}}</option></select></label><label>عملية التمويل<select v-model="draft.transfer_id" required aria-label="عملية التمويل للاسترجاع"><option value="" disabled>اختر عملية التمويل</option><option v-for="row in eligible" :key="row.id" :value="row.id" :disabled="!open(row)">{{row.id}} · {{money(row.amount)}} {{vm.currencyLabel(row.currency)}} · {{open(row)?'ضمن المهلة':'انتهت المهلة'}}</option></select></label><label>المبلغ المسترجع · {{vm.currencyLabel(vm.currency.value)}}<input v-model="draft.amount" type="text" inputmode="decimal" v-money required></label><label>سبب الاسترجاع<input v-model="draft.reason" required maxlength="1000"></label><div class="recovery-available"><span>المتاح للاسترجاع</span><strong class="ops-number">{{money(limit)}} {{vm.currencyLabel(vm.currency.value)}}</strong><button type="button" class="btn" :disabled="!positive(limit) || vm.busy.value" @click="draft.amount=limit">كامل المتاح</button></div></div><p v-if="selected" class="help">{{open(selected)?'ضمن المهلة':'انتهت المهلة'}} · آخر موعد: {{time(selected.recovery_deadline)}}</p><p v-if="transfers.state.error" class="notice warn" role="alert">{{transfers.state.error}}</p><FinancePagination v-if="draft.to" :meta="transfers.state.meta" :busy="transfers.state.loading" @page="loadTransfers" /><div class="actions"><button class="btn primary" :disabled="vm.busy.value || !draft.to || !selected || !open(selected) || !positive(draft.amount) || !draft.reason.trim()">استرجاع إلى محفظتي</button></div></form><p v-else-if="!vm.service.value" class="card empty">اختر محفظة محددة للاسترجاع</p><section class="card recovery-history"><h3>سجل استرجاع الرصيد</h3><p v-if="history.state.error" class="notice warn" role="alert">{{history.state.error}}</p><p v-if="history.state.loading" class="read-loading caption">جارٍ تحميل السجل…</p><TablePanel class="tablewrap"><table><thead><tr><th>التاريخ</th><th>الحساب المسترجع منه</th><th>الوكيل المستلم</th><th>المبلغ</th><th>السبب</th><th>رقم العملية</th></tr></thead><tbody><tr v-for="row in history.state.rows" :key="row.id"><td>{{time(row.created_at)}}</td><td>{{row.to_account_name || vm.name(row.to_account_id)}}</td><td>{{row.from_account_name || vm.name(row.from_account_id)}}</td><td>{{money(row.amount)}} {{vm.currencyLabel(row.currency || vm.currency.value)}}</td><td>{{row.reason}}</td><td>{{row.id}}</td></tr><tr v-if="!history.state.rows.length && !history.state.loading"><td colspan="6" class="empty">لا توجد عمليات استرجاع</td></tr></tbody></table></TablePanel><FinancePagination :meta="history.state.meta" :busy="history.state.loading" @page="loadHistory" /></section></div></template>
